code.rust:
fn is_palindrome(text: &str) -> i32 {
    let chars: Vec<char> = text.chars().collect();
    // Signed indices avoid underflow when the string is empty (len - 1 == -1).
    let mut left: isize = 0;
    let mut right: isize = chars.len() as isize - 1;
    while left < right {
        if chars[left as usize] != chars[right as usize] {
            return 0;
        }
        left += 1;
        right -= 1;
    }
    1
}

fn main() {
    println!("{}", is_palindrome("level"));
}

